const staticData = $getWorkflowStaticData('global');
if (!staticData.mods) staticData.mods = {};

const changed = [];
for (const item of $input.all()) {
  const name = item.json.table_name;
  const mods = item.json.mod_count;
  if (staticData.mods[name] !== mods) {
    staticData.mods[name] = mods;
    changed.push({ json: { table_name: name } });
  }
}

if (changed.length === 0) return [{ json: { _skip: true } }];
return changed;

const sheetsResponse = $('Get Sheet IDs').first().json;
const sheetMap = {};
for (const s of sheetsResponse.sheets) {
  sheetMap[s.properties.title] = s.properties.sheetId;
}

const tables = $('Any Changes?').all().map(i => i.json.table_name);
const result = tables.map(t => ({
  json: { table_name: t, sheet_id: sheetMap[t] ?? null }
}));
return result;

const rows = $input.all().map(i => i.json);
const tableName = $('Loop Over Tables').item.json.table_name;
let sheetId = $('Loop Over Tables').item.json.sheet_id;

if (rows.length === 0) {
  return [{ json: { _empty: true } }];
}

function hashCode(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = ((h << 5) - h) + s.charCodeAt(i) | 0;
  return Math.abs(h);
}

const headers = Object.keys(rows[0]);
const csvLines = [headers.join(',')];
for (const row of rows) {
  csvLines.push(headers.map(h => {
    const v = String(row[h] ?? '');
    return (v.includes(',') || v.includes('"') || v.includes('\n')) ? '"' + v.replace(/"/g, '""') + '"' : v;
  }).join(','));
}

const requests = [];

if (sheetId == null) {
  sheetId = hashCode(tableName);
  requests.push({ addSheet: { properties: { sheetId, title: tableName } } });
}
requests.push({ updateCells: { range: { sheetId }, fields: 'userEnteredValue' } });
requests.push({ pasteData: { coordinate: { sheetId, rowIndex: 0, columnIndex: 0 }, data: csvLines.join('\n'), type: 'PASTE_NORMAL', delimiter: ',' } });

return [{ json: { _empty: false, body: { requests } } }];
